@implements IDisposable
@inject sv_e58c98cfe89047d58c2cbb55fb51bd80.Services.WarehouseState WarehouseState
@inject sv_e58c98cfe89047d58c2cbb55fb51bd80.Services.InventoryAlertService AlertService

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-header">
        <strong>Current Warehouse:</strong> @WarehouseState.Current.Name
    </div>
    <div class="card-body">
        <h5 class="card-title">Low Stock Alerts</h5>
        <p class="card-text">
            @if (AlertService.LowStockCount > 0)
            {
                <span class="text-danger fw-bold">
                    ⚠️ @AlertService.LowStockCount item(s) below minimum stock levels
                </span>
            }
            else
            {
                <span class="text-success fw-bold">
                    ✅ All items are above minimum stock levels
                </span>
            }
        </p>
        <p class="text-muted small">
            Polling every 10 seconds for warehouse <code>@WarehouseState.Current.Id</code>.
            Last update: @_lastUpdate.ToString("HH:mm:ss")
        </p>
    </div>
</div>

@code {
    private Action? _alertHandler;
    private Action? _warehouseHandler;
    private DateTime _lastUpdate = DateTime.Now;

    protected override void OnInitialized()
    {
        // Subscribe to alert changes
        _alertHandler = () => InvokeAsync(() =>
        {
            _lastUpdate = DateTime.Now;
            StateHasChanged();
        });
        AlertService.OnAlertCountChanged += _alertHandler;

        // Subscribe to warehouse changes
        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        WarehouseState.OnChange += _warehouseHandler;

        // Start polling while this page is visible
        AlertService.StartPolling();
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= _alertHandler;
        WarehouseState.OnChange -= _warehouseHandler;
        AlertService.StopPolling();
    }
}

